// Temporary interfaces for gRPC services (should be generated from protobuf)
type CacheCoordinatorClient interface {
	SyncOperation(ctx context.Context, in *SyncOperation, opts ...grpc.CallOption) (*SyncResponse, error)
	Heartbeat(ctx context.Context, in *NodeInfo, opts ...grpc.CallOption) (*HeartbeatResponse, error)
	DiscoverNodes(ctx context.Context, in *DiscoverNodesRequest, opts ...grpc.CallOption) (*DiscoverNodesResponse, error)
	BroadcastOperation(ctx context.Context, in *BroadcastOperationRequest, opts ...grpc.CallOption) (*SyncResponse, error)
	SendToNode(ctx context.Context, in *SendToNodeRequest, opts ...grpc.CallOption) (*SyncResponse, error)
	GetNodeHealth(ctx context.Context, in *GetNodeHealthRequest, opts ...grpc.CallOption) (*GetNodeHealthResponse, error)
}

type CacheCoordinatorServer interface {
	SyncOperation(context.Context, *SyncOperation) (*SyncResponse, error)
	Heartbeat(context.Context, *NodeInfo) (*HeartbeatResponse, error)
}

// Temporary response types
type SyncResponse struct {
	Success bool
	Message string
}

type HeartbeatResponse struct {
	Success bool
	Message string
}

type DiscoverNodesRequest struct {
	ClusterName      string
	RequestingNodeId string
}

type DiscoverNodesResponse struct {
	Success bool
	Nodes   []*NodeMessage
}

type NodeMessage struct {
	Id       string
	Status   string
	LastSeen *timestamppb.Timestamp
	Version  string
	Metadata map[string]string
}

type BroadcastOperationRequest struct {
	Operation *SyncOperationMessage
}

type SendToNodeRequest struct {
	TargetNodeId string
	Operation    *SyncOperationMessage
}

type SyncOperationMessage struct {
	Id        string
	Type      string
	Key       string
	Value     []byte
	NodeId    string
	Timestamp *timestamppb.Timestamp
}

type GetNodeHealthRequest struct {
	NodeId string
}

type GetNodeHealthResponse struct {
	Health *NodeHealthMessage
}

type NodeHealthMessage struct {
	NodeId        string
	Status        string
	LastHeartbeat *timestamppb.Timestamp
	IsReachable   bool
	ResponseTime  int64
	Version       string
}

