// GRPCCoordinator implementa NodeCoordinator usando gRPC
// Segue padrão Adapter para integração com protocolo gRPC
type GRPCCoordinator struct {
	// Configuração e identificação
	config      *GRPCConfig
	nodeID      string
	clusterName string
	
	// Estado interno
	isRunning   bool
	nodes       map[string]*NodeInfo
	
	// Canais de comunicação (Event-Driven)
	syncChan        chan *SyncOperation
	heartbeatChan   chan *NodeInfo
	discoveryEvents chan *DiscoveryEvent
	opsChan         chan *SyncOperation
	stopChan        chan struct{}
	
	// Controle de concorrência
	mutex      sync.RWMutex
	nodesMutex sync.RWMutex
	
	// Dependências injetadas (DI)
	logger Logger
	
	// Métricas e monitoramento
	metrics *CoordinatorMetrics
	
	// Servidor gRPC e componentes
	server         *grpc.Server
	listener       net.Listener
	healthServer   *health.Server
	clients        map[string]CacheCoordinatorClient
	clientsMutex   sync.RWMutex
	heartbeatTicker *time.Ticker
	
	// Controle de lifecycle
	ctx    context.Context
	cancel context.CancelFunc
	wg     sync.WaitGroup
}

// NewGRPCCoordinator cria novo coordenador gRPC seguindo padrão Factory
func NewGRPCCoordinator(config *GRPCConfig, nodeID, clusterName string, logger Logger, metrics *CoordinatorMetrics) (*GRPCCoordinator, error) {
	if config == nil {
		return nil, fmt.Errorf("grpc config cannot be nil")
	}
	
	if nodeID == "" {
		return nil, fmt.Errorf("node ID cannot be empty")
	}
	
	if clusterName == "" {
		return nil, fmt.Errorf("cluster name cannot be empty")
	}
	
	coordinator := &GRPCCoordinator{
		config:          config,
		nodeID:          nodeID,
		clusterName:     clusterName,
		nodes:           make(map[string]*NodeInfo),
		syncChan:        make(chan *SyncOperation, 1000),
		heartbeatChan:   make(chan *NodeInfo, 100),
		discoveryEvents: make(chan *DiscoveryEvent, 100),
		opsChan:         make(chan *SyncOperation, 1000),
		stopChan:        make(chan struct{}),
		clients:         make(map[string]CacheCoordinatorClient),
		logger:          logger,
		metrics:         &CoordinatorMetrics{},
	}
	
	return coordinator, nil
}

// Start inicia o coordenador gRPC
func (g *GRPCCoordinator) Start(ctx context.Context) error {
	g.mutex.Lock()
	defer g.mutex.Unlock()
	
	if g.isRunning {
		return fmt.Errorf("coordinator is already running")
	}
	
	// Criar listener
	address := fmt.Sprintf("%s:%d", g.config.Host, g.config.Port)
	listener, err := net.Listen("tcp", address)
	if err != nil {
		return fmt.Errorf("failed to listen on %s: %w", address, err)
	}
	g.listener = listener
	
	// Configurar servidor gRPC
	opts := []grpc.ServerOption{
		grpc.MaxRecvMsgSize(g.config.MaxMessageSize),
		grpc.MaxSendMsgSize(g.config.MaxMessageSize),
	}
	
	if g.config.TLS != nil && g.config.TLS.Enabled {
		// TODO: Implementar TLS quando necessário
		g.logger.Info("TLS configuration detected but not implemented yet", nil)
	}
	
	g.server = grpc.NewServer(opts...)
	
	// Registrar serviços
	RegisterCacheCoordinatorServer(g.server, g)
	
	// Health check
	g.healthServer = health.NewServer()
	grpc_health_v1.RegisterHealthServer(g.server, g.healthServer)
	g.healthServer.SetServingStatus("", grpc_health_v1.HealthCheckResponse_SERVING)
	
	// Registrar este nó
	nodeInfo := &NodeInfo{
		ID:       g.nodeID,
		Status:   NodeStatusActive,
		LastSeen: time.Now(),
		Version:  "1.0.0",
		Metadata: map[string]string{
			"cluster": g.clusterName,
			"type":    "grpc_coordinator",
			"address": address,
		},
	}
	
	g.nodesMutex.Lock()
	g.nodes[g.nodeID] = nodeInfo
	g.nodesMutex.Unlock()
	
	g.isRunning = true
	
	// Iniciar servidor em goroutine
	go func() {
		if err := g.server.Serve(listener); err != nil {
			g.logger.Error("gRPC server failed", err, map[string]interface{}{
				"address": address,
			})
		}
	}()
	
	// Iniciar heartbeat
	go g.heartbeatHandler(ctx)
	
	// Conectar a nós conhecidos
	go g.connectToKnownNodes(ctx)
	
	g.logger.Info("gRPC coordinator started", map[string]interface{}{
		"node_id": g.nodeID,
		"address": address,
		"cluster": g.clusterName,
	})
	
	return nil
}

// Stop para o coordenador
func (g *GRPCCoordinator) Stop(ctx context.Context) error {
	g.mutex.Lock()
	defer g.mutex.Unlock()
	
	if !g.isRunning {
		return nil
	}
	
	// Parar heartbeat
	if g.heartbeatTicker != nil {
		g.heartbeatTicker.Stop()
	}
	
	// Fechar conexões com clientes
	g.clientsMutex.Lock()
	for nodeID, client := range g.clients {
		if conn, ok := client.(interface{ GetConnection() *grpc.ClientConn }); ok {
			conn.GetConnection().Close()
		}
		delete(g.clients, nodeID)
	}
	g.clientsMutex.Unlock()
	
	// Parar servidor
	if g.server != nil {
		g.server.GracefulStop()
	}
	
	// Fechar listener
	if g.listener != nil {
		g.listener.Close()
	}
	
	// Sinalizar parada
	close(g.stopChan)
	
	g.isRunning = false
	
	g.logger.Info("gRPC coordinator stopped", map[string]interface{}{
		"node_id": g.nodeID,
	})
	
	return nil
}

// IsRunning verifica se o coordenador está ativo
func (g *GRPCCoordinator) IsRunning() bool {
	g.mutex.RLock()
	defer g.mutex.RUnlock()
	return g.isRunning
}

// DiscoverNodes implementa descoberta de nós via gRPC
func (g *GRPCCoordinator) DiscoverNodes(ctx context.Context) ([]*NodeInfo, error) {
	g.nodesMutex.RLock()
	nodes := make([]*NodeInfo, 0, len(g.nodes))
	for _, node := range g.nodes {
		// Criar cópia para evitar modificações concorrentes
		nodeCopy := *node
		nodes = append(nodes, &nodeCopy)
	}
	g.nodesMutex.RUnlock()
	
	// Tentar descobrir nós via clientes conectados
	g.clientsMutex.RLock()
	clients := make(map[string]CacheCoordinatorClient)
	for k, v := range g.clients {
		clients[k] = v
	}
	g.clientsMutex.RUnlock()
	
	for nodeID, client := range clients {
		if nodeID == g.nodeID {
			continue
		}
		
		req := &DiscoverNodesRequest{
			ClusterName:       g.clusterName,
			RequestingNodeId:  g.nodeID,
		}
		
		resp, err := client.DiscoverNodes(ctx, req)
		if err != nil {
			g.logger.Error("Failed to discover nodes from peer", err, map[string]interface{}{
				"peer_node_id": nodeID,
			})
			continue
		}
		
		if resp.Success {
			for _, nodeMsg := range resp.Nodes {
				node := g.convertFromNodeMessage(nodeMsg)
				
				// Adicionar se não existir
				g.nodesMutex.Lock()
				if _, exists := g.nodes[node.ID]; !exists {
					g.nodes[node.ID] = node
					nodes = append(nodes, node)
				}
				g.nodesMutex.Unlock()
			}
		}
	}
	
	return nodes, nil
}

// RegisterNode registra um novo nó
func (g *GRPCCoordinator) RegisterNode(ctx context.Context, node *NodeInfo) error {
	if node == nil {
		return fmt.Errorf("node info cannot be nil")
	}
	
	node.LastSeen = time.Now()
	
	g.nodesMutex.Lock()
	g.nodes[node.ID] = node
	g.nodesMutex.Unlock()
	
	// Tentar conectar ao novo nó se tiver endereço
	if address, exists := node.Metadata["address"]; exists && node.ID != g.nodeID {
		go g.connectToNode(ctx, node.ID, address)
	}
	
	g.logger.Info("Node registered", map[string]interface{}{
		"node_id": node.ID,
		"status":  node.Status,
	})
	
	return nil
}

// UnregisterNode remove um nó
func (g *GRPCCoordinator) UnregisterNode(ctx context.Context, nodeID string) error {
	g.nodesMutex.Lock()
	delete(g.nodes, nodeID)
	g.nodesMutex.Unlock()
	
	// Fechar conexão se existir
	g.clientsMutex.Lock()
	if client, exists := g.clients[nodeID]; exists {
		if conn, ok := client.(interface{ GetConnection() *grpc.ClientConn }); ok {
			conn.GetConnection().Close()
		}
		delete(g.clients, nodeID)
	}
	g.clientsMutex.Unlock()
	
	g.logger.Info("Node unregistered", map[string]interface{}{
		"node_id": nodeID,
	})
	
	return nil
}

// UpdateNodeStatus atualiza status de um nó
func (g *GRPCCoordinator) UpdateNodeStatus(ctx context.Context, nodeID string, status NodeStatus) error {
	g.nodesMutex.Lock()
	if node, exists := g.nodes[nodeID]; exists {
		node.Status = status
		node.LastSeen = time.Now()
	}
	g.nodesMutex.Unlock()
	
	return nil
}

// BroadcastOperation envia operação para todos os nós
func (g *GRPCCoordinator) BroadcastOperation(ctx context.Context, op *SyncOperation) error {
	if op == nil {
		return fmt.Errorf("sync operation cannot be nil")
	}
	
	op.NodeID = g.nodeID
	op.Timestamp = time.Now()
	
	opMsg := g.convertToSyncOperationMessage(op)
	req := &BroadcastOperationRequest{
		Operation: opMsg,
	}
	
	g.clientsMutex.RLock()
	clients := make(map[string]CacheCoordinatorClient)
	for k, v := range g.clients {
		clients[k] = v
	}
	g.clientsMutex.RUnlock()
	
	var wg sync.WaitGroup
	nodesReached := int32(0)
	
	for nodeID, client := range clients {
		if nodeID == g.nodeID {
			continue
		}
		
		wg.Add(1)
		go func(nID string, c CacheCoordinatorClient) {
			defer wg.Done()
			
			if _, err := c.BroadcastOperation(ctx, req); err != nil {
				g.logger.Error("Failed to broadcast to node", err, map[string]interface{}{
					"target_node_id": nID,
					"operation_id":   op.ID,
				})
			} else {
				nodesReached++
			}
		}(nodeID, client)
	}
	
	wg.Wait()
	
	g.metrics.RecordCustomMetric("sync_operations_sent", float64(nodesReached))
	
	return nil
}

// SendToNode envia operação para nó específico
func (g *GRPCCoordinator) SendToNode(ctx context.Context, nodeID string, op *SyncOperation) error {
	if op == nil {
		return fmt.Errorf("sync operation cannot be nil")
	}
	
	g.clientsMutex.RLock()
	client, exists := g.clients[nodeID]
	g.clientsMutex.RUnlock()
	
	if !exists {
		return fmt.Errorf("no connection to node: %s", nodeID)
	}
	
	op.NodeID = g.nodeID
	op.Timestamp = time.Now()
	
	opMsg := g.convertToSyncOperationMessage(op)
	req := &SendToNodeRequest{
		TargetNodeId: nodeID,
		Operation:    opMsg,
	}
	
	_, err := client.SendToNode(ctx, req)
	return err
}

// ReceiveOperations retorna canal para receber operações
func (g *GRPCCoordinator) ReceiveOperations(ctx context.Context) (<-chan *SyncOperation, error) {
	if !g.isRunning {
		return nil, fmt.Errorf("coordinator is not running")
	}
	
	return g.opsChan, nil
}

// SendHeartbeat envia heartbeat
func (g *GRPCCoordinator) SendHeartbeat(ctx context.Context, nodeInfo *NodeInfo) error {
	return g.RegisterNode(ctx, nodeInfo)
}

// GetNodeHealth obtém saúde de um nó
func (g *GRPCCoordinator) GetNodeHealth(nodeID string) (*NodeHealth, error) {
	g.nodesMutex.RLock()
	node, exists := g.nodes[nodeID]
	g.nodesMutex.RUnlock()
	
	if !exists {
		return nil, fmt.Errorf("node not found: %s", nodeID)
	}
	
	health := &NodeHealth{
		NodeID:        node.ID,
		Status:        node.Status,
		LastHeartbeat: node.LastSeen,
		IsReachable:   time.Since(node.LastSeen) < 2*time.Minute,
		Version:       node.Version,
	}
	
	// Testar conectividade se tiver cliente
	g.clientsMutex.RLock()
	client, hasClient := g.clients[nodeID]
	g.clientsMutex.RUnlock()
	
	if hasClient && nodeID != g.nodeID {
		start := time.Now()
		req := &GetNodeHealthRequest{NodeId: nodeID}
		
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		
		_, err := client.GetNodeHealth(ctx, req)
		if err == nil {
			health.ResponseTime = time.Since(start)
			health.IsReachable = true
		} else {
			health.ResponseTime = time.Duration(0)
			health.IsReachable = false
		}
	}
	
	return health, nil
}

// GetCoordinatorType retorna o tipo do coordenador
func (g *GRPCCoordinator) GetCoordinatorType() CoordinatorType {
	return CoordinatorGRPC
}

// UpdateConfig atualiza configuração
func (g *GRPCCoordinator) UpdateConfig(config interface{}) error {
	grpcConfig, ok := config.(*GRPCConfig)
	if !ok {
		return fmt.Errorf("invalid config type, expected *GRPCConfig")
	}
	
	g.mutex.Lock()
	defer g.mutex.Unlock()
	
	g.config = grpcConfig
	
	return nil
}



// updateMetrics atualiza métricas do coordenador
func (g *GRPCCoordinator) updateMetrics() {
	g.mutex.RLock()
	defer g.mutex.RUnlock()
	
	if g.metrics != nil {
		g.metrics.ConnectedNodes = int64(len(g.nodes))
		g.metrics.LastUpdate = time.Now()
	}
}

// Métodos auxiliares de conversão

func (g *GRPCCoordinator) convertFromNodeMessage(msg *NodeMessage) *NodeInfo {
	return &NodeInfo{
		ID:       msg.Id,
		Status:   NodeStatus(msg.Status),
		LastSeen: msg.LastSeen.AsTime(),
		Version:  msg.Version,
		Metadata: msg.Metadata,
	}
}

func (g *GRPCCoordinator) convertToSyncOperationMessage(op *SyncOperation) *SyncOperationMessage {
	var valueBytes []byte
	if op.Value != nil {
		// Serialize the value to bytes (simple JSON serialization)
		if data, err := json.Marshal(op.Value); err == nil {
			valueBytes = data
		}
	}
	
	return &SyncOperationMessage{
		Id:        op.ID,
		Type:      string(op.Type),
		Key:       op.Key,
		Value:     valueBytes,
		NodeId:    op.NodeID,
		Timestamp: timestamppb.New(op.Timestamp),
	}
}

// Métodos auxiliares de conectividade

func (g *GRPCCoordinator) connectToKnownNodes(ctx context.Context) {
	for _, address := range g.config.KnownNodes {
		go g.connectToNodeByAddress(ctx, address)
	}
}

func (g *GRPCCoordinator) connectToNode(ctx context.Context, nodeID, address string) {
	conn, err := grpc.DialContext(ctx, address, 
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithBlock(),
	)
	if err != nil {
		g.logger.Error("Failed to connect to node", err, map[string]interface{}{
			"node_id": nodeID,
			"address": address,
		})
		return
	}
	
	client := NewCacheCoordinatorClient(conn)
	
	g.clientsMutex.Lock()
	g.clients[nodeID] = client
	g.clientsMutex.Unlock()
	
	g.logger.Info("Connected to node", map[string]interface{}{
		"node_id": nodeID,
		"address": address,
	})
}

func (g *GRPCCoordinator) connectToNodeByAddress(ctx context.Context, address string) {
	conn, err := grpc.DialContext(ctx, address,
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
	if err != nil {
		g.logger.Error("Failed to connect to address", err, map[string]interface{}{
			"address": address,
		})
		return
	}
	
	client := NewCacheCoordinatorClient(conn)
	
	// Tentar descobrir o ID do nó
	req := &DiscoverNodesRequest{
		ClusterName:      g.clusterName,
		RequestingNodeId: g.nodeID,
	}
	
	resp, err := client.DiscoverNodes(ctx, req)
	if err != nil {
		conn.Close()
		return
	}
	
	// Assumir que o primeiro nó é o nó de destino
	if len(resp.Nodes) > 0 {
		nodeID := resp.Nodes[0].Id
		
		g.clientsMutex.Lock()
		g.clients[nodeID] = client
		g.clientsMutex.Unlock()
		
		g.logger.Info("Connected to node by address", map[string]interface{}{
			"node_id": nodeID,
			"address": address,
		})
	}
}

func (g *GRPCCoordinator) heartbeatHandler(ctx context.Context) {
	g.heartbeatTicker = time.NewTicker(30 * time.Second)
	defer g.heartbeatTicker.Stop()
	
	for {
		select {
		case <-g.stopChan:
			return
		case <-ctx.Done():
			return
		case <-g.heartbeatTicker.C:
			nodeInfo := &NodeInfo{
				ID:       g.nodeID,
				Status:   NodeStatusActive,
				LastSeen: time.Now(),
				Version:  "1.0.0",
				Metadata: map[string]string{
					"cluster": g.clusterName,
					"type":    "grpc_coordinator",
				},
			}
			
			if err := g.RegisterNode(ctx, nodeInfo); err != nil {
				g.logger.Error("Failed to send heartbeat", err, map[string]interface{}{
					"node_id": g.nodeID,
				})
			}
		}
	}
}

// Implementação da interface CacheCoordinatorServer

// SyncOperation handles synchronization operations from other nodes
func (g *GRPCCoordinator) SyncOperation(ctx context.Context, op *SyncOperation) (*SyncResponse, error) {
	if op == nil {
		return &SyncResponse{
			Success: false,
			Message: "operation cannot be nil",
		}, nil
	}

	// Forward operation to local processing channel
	select {
	case g.opsChan <- op:
		return &SyncResponse{
			Success: true,
			Message: "operation queued successfully",
		}, nil
	case <-ctx.Done():
		return &SyncResponse{
			Success: false,
			Message: "context cancelled",
		}, ctx.Err()
	default:
		return &SyncResponse{
			Success: false,
			Message: "operation queue is full",
		}, nil
	}
}

// Heartbeat handles heartbeat requests from other nodes
func (g *GRPCCoordinator) Heartbeat(ctx context.Context, nodeInfo *NodeInfo) (*HeartbeatResponse, error) {
	if nodeInfo == nil {
		return &HeartbeatResponse{
			Success: false,
			Message: "node info cannot be nil",
		}, nil
	}

	// Update node information
	g.nodesMutex.Lock()
	nodeInfo.LastSeen = time.Now()
	g.nodes[nodeInfo.ID] = nodeInfo
	g.nodesMutex.Unlock()

	g.logger.Info("Received heartbeat", map[string]interface{}{
		"node_id": nodeInfo.ID,
		"status":  nodeInfo.Status,
	})

	return &HeartbeatResponse{
		Success: true,
		Message: "heartbeat received",
	}, nil
}